// ─── File: ResilienceDemo.java ───
// Runnable demo: circuit breaker trips open; retry handles blips; aspect-order gotcha shown.
package com.bank.resilience;

import java.util.logging.*;

public class ResilienceDemo {

    private static final Logger log = Logger.getLogger("Resilience");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        CreditScoreClient client = new CreditScoreClient();
        SimpleCircuitBreaker cb = new SimpleCircuitBreaker(4, 3);  // open after 4 fails in window of ... trial after
        client.setDown(true);  // simulate the provider being DOWN

        // 1) Circuit breaker trips open and fails fast with a fallback.
        for (int i = 1; i <= 7; i++) {
            final int n = i;
            try {
                int score = cb.call(() -> client.getScore("SAV2001"));
                log.info(() -> "call " + n + " score=" + score);
            } catch (CallNotPermittedException e) {
                log.warning(() -> "call " + n + " FAST-FAIL (circuit OPEN) → fallback score=600");
            } catch (RuntimeException e) {
                log.severe(() -> "call " + n + " failed: " + e.getMessage());
            }
        }

        // 2) WRONG order: Retry wraps CircuitBreaker → retries CallNotPermittedException.
        Retrier retry = new Retrier(3);
        log.info("── WRONG order: Retry(CircuitBreaker) retries an OPEN circuit ──");
        try {
            retry.run(() -> cb.call(() -> client.getScore("SAV2001")));
        } catch (Exception e) {
            log.severe(() -> "wasted " + retry.lastAttempts()
                    + " retries against an OPEN circuit → " + e.getClass().getSimpleName());
        }

        // 3) RIGHT order: CircuitBreaker wraps Retry → open circuit fails fast, no retry.
        log.info("── RIGHT order: CircuitBreaker(Retry) fails fast when OPEN ──");
        try {
            cb.call(() -> retry.run(() -> client.getScore("SAV2001")));
        } catch (CallNotPermittedException e) {
            log.info("fast-fail immediately, zero wasted retries → fallback score=600");
        }
    }
}

// ─── client/CreditScoreClient.java (the flaky external dependency) ───
class CreditScoreClient {
    private boolean down;
    void setDown(boolean down) { this.down = down; }
    int getScore(String accountId) {
        if (down) throw new RuntimeException("credit-score provider timeout");
        return 780;   // healthy score for Rajesh
    }
}

// ─── breaker/SimpleCircuitBreaker.java (CLOSED → OPEN → HALF_OPEN) ───
class SimpleCircuitBreaker {
    private static final Logger log = Logger.getLogger("Resilience");
    enum State { CLOSED, OPEN, HALF_OPEN }
    private State state = State.CLOSED;
    private int consecutiveFailures = 0;
    private final int failThreshold;       // open after this many failures
    private long openedAt = 0;
    private final long waitMs = 50;        // short for demo
    SimpleCircuitBreaker(int failThreshold, int ignored) { this.failThreshold = failThreshold; }

    <T> T call(java.util.function.Supplier<T> op) {
        if (state == State.OPEN) {
            if (System.currentTimeMillis() - openedAt >= waitMs) {
                state = State.HALF_OPEN;                 // time to test recovery
                log.fine("circuit → HALF_OPEN (trial call)");
            } else {
                throw new CallNotPermittedException();   // reject without calling dependency
            }
        }
        try {
            T result = op.get();
            consecutiveFailures = 0;
            if (state == State.HALF_OPEN) { state = State.CLOSED; log.info("circuit → CLOSED (recovered)"); }
            return result;
        } catch (RuntimeException ex) {
            consecutiveFailures++;
            if (consecutiveFailures >= failThreshold || state == State.HALF_OPEN) {
                state = State.OPEN; openedAt = System.currentTimeMillis();
                log.warning(() -> "circuit → OPEN after " + consecutiveFailures + " failures");
            }
            throw ex;
        }
    }
}

// ─── CallNotPermittedException (thrown when circuit is OPEN) ───
class CallNotPermittedException extends RuntimeException {
    CallNotPermittedException() { super("circuit is OPEN — call not permitted"); }
}

// ─── retry/Retrier.java (simple bounded retry) ───
class Retrier {
    private final int maxAttempts; private int attempts;
    Retrier(int maxAttempts) { this.maxAttempts = maxAttempts; }
    int lastAttempts() { return attempts; }
    <T> T run(java.util.function.Supplier<T> op) {
        attempts = 0; RuntimeException last = null;
        while (attempts < maxAttempts) {
            attempts++;
            try { return op.get(); }
            catch (RuntimeException e) { last = e; }   // WRONG order retries CallNotPermitted too
        }
        throw last;
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
